mapper.sql:
WITH objRec AS( SELECT REG_CODE, MDATE, BALANCE_AMT, PRD_QTY FROM( SELECT REG_CODE, MDATE, BALANCE_AMT, PRD_QTY, ROW_NUMBER() over( partition by REG_CODE ORDER BY MDATE DESC ) AS durMDateNo FROM( SELECT A.REG_CODE, B.MDATE, B.BALANCE_AMT, B.PRD_QTY, ROW_NUMBER() over( partition by A.REG_CODE , B.MDATE ORDER BY B.STATUS DESC ,B.UPDATE_TIME DESC) AS durStatusNo FROM CHB_PRD_BASEINFO A LEFT JOIN CHB_PRD_DEAL_SUB B ON (A.REG_CODE = B.PROD_REGIST_CODE
#{orgCode,jdbcType=VARCHAR}
) WHERE A.STATUS != 'D'
#{operateMode,jdbcType=VARCHAR}
AND B.STATUS IN ('01','02') AND TO_DATE(TO_CHAR(B.MDATE, 'yyyy-MM-dd'), 'yyyy-MM-dd') <= TO_DATE(#{searchDate,jdbcType=VARCHAR},'yyyy-MM-dd') ) WHERE durStatusNo = 1 ) WHERE durMDateNo = 1 OR durMDateNo = 2 )
